import { BaseApi } from '../../shared/infrastructure/base-api.js';
import { BaseEndpoint } from '../../shared/infrastructure/base-endpoint.js';

const demandForecastsEndpointPath = import.meta.env.VITE_DEMAND_FORECASTS_ENDPOINT_PATH;

/**
 * Infrastructure adapter of the Demand Forecasting Bounded Context. The
 * forecast is generated by the API with the Machine Learning model (ONNX),
 * the sales history, the Peruvian calendar and the Open-Meteo weather.
 */
export class ForecastApi extends BaseApi {
  #demandForecastsEndpoint;

  constructor() {
    super();
    this.#demandForecastsEndpoint = new BaseEndpoint(this, demandForecastsEndpointPath);
  }

  getDemandForecasts() { return this.#demandForecastsEndpoint.getAll(); }

  /** @param {number} [horizonDays] */
  generateDemandForecast(horizonDays = 7) { return this.#demandForecastsEndpoint.create({ horizonDays }); }

  getModel() { return this.#demandForecastsEndpoint.getPath('model'); }
}
